/* MIT. Experimental persistent-state check; never prints generated bytes.
 * Success consumes and discards one 32-byte request. Not an entropy-quality
 * test, storage durability guarantee, or SSH service readiness check.
 */
#include <stdio.h>
#include "entropy.h"

int main(int argc, char **argv)
{
    unsigned char bytes[32];
    volatile unsigned char *p;
    unsigned int i;
    ssize_t result;
    (void)argv;
    if (argc != 1) {
        fputs("Usage: rngcheck (consumes one request)\n", stderr);
        return 2;
    }
    result = elkssh_persistent_getrandom(bytes, sizeof bytes, 0);
    p = bytes;
    for (i = 0; i < sizeof bytes; i++) p[i] = 0;
    if (result != sizeof bytes) {
        puts("RNGCHECK REFUSED");
        return 1;
    }
    puts("RNGCHECK OK: request consumed; output discarded");
    return 0;
}
